// Run in frontend from CI: node node_modules/vite-node/vite-node.mjs scripts/prepareWatermarkPrintPack.mjs
// Synthetic printable challenge PDFs generated by QRed itself, never a third-party stamp.
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { mkdirSync, writeFileSync } from "node:fs";
import { resolve, join } from "node:path";
import { PDFDocument, StandardFonts, rgb } from "pdf-lib";
import { sealPdfInBrowser } from "../src/pdfClientSeal.js";
import { scanPdfPage } from "../src/verifier/scanPdf.js";
import { withPdfDocument, renderPdfPage } from "../src/pdf/readPdfText.js";
import { verifyQRedSeals } from "../src/qredVerifier.js";
import { createQRedQrSymbol } from "../src/qredQr.js";

const out = resolve(process.env.QRED_PRINT_OUTPUT || "../print-watermark-samples");
mkdirSync(out, { recursive: true });
const signing = {
  privateKey: "txzqca0BtMpjGTzQWh_FnBgQyiGjuf1mdhBMzCutAes",
  publicKey: "eC4VZfi1rwwnKF-m5H0wg5kJ9OGeNhPddtr2yQI5i0Q",
};
const pageSize = [612, 792]; // US Letter, 8.5 x 11 inches.
const stamp = (page, text, x, y, size, color = rgb(0, 0, 0), font) =>
  page.drawText(text, { x, y, size, color, font });

function nextRand(seed) {
  let state = seed >>> 0;
  return () => {
    state ^= state << 13; state ^= state >>> 17; state ^= state << 5;
    return state >>> 0;
  };
}
const ink = {
  navy: rgb(0.15, 0.23, 0.37),
  blue: rgb(0.08, 0.42, 0.72),
  maroon: rgb(0.65, 0.18, 0.24),
  green: rgb(0.05, 0.48, 0.27),
  gray: rgb(0.36, 0.40, 0.46),
};

async function sampleDocument(kind) {
  const pdf = await PDFDocument.create();
  const page = pdf.addPage(pageSize);
  const regular = await pdf.embedFont(StandardFonts.Helvetica);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const mono = await pdf.embedFont(StandardFonts.Courier);
  page.drawRectangle({ x: 0, y: 0, width: 612, height: 792, color: rgb(1, 1, 1) });
  const title = kind === "single-black" ? "QRED PRINT TEST A - STANDARD TEXT"
    : kind === "single-color" ? "QRED PRINT TEST B - COLORED TEXT / LOGO"
      : "QRED PRINT TEST C - 2 x 2 DENSE TEXT";
  stamp(page, title, 42, 754, 13.5, ink.navy, bold);
  stamp(page, "SYNTHETIC EXAMPLE - DO NOT USE AS AN OFFICIAL DOCUMENT", 42, 735, 8.5, ink.maroon, regular);
  page.drawLine({ start: { x: 42, y: 728 }, end: { x: 570, y: 728 },
    thickness: 0.65, color: ink.gray });
  if (kind === "single-black") {
    stamp(page, "Delivery manifest / signature and page watermark challenge", 42, 703, 11, ink.navy, bold);
    const rand = nextRand(0x93c70a61);
    for (let i = 0; i < 24; i++) {
      const value = rand().toString(16).padStart(8, "0").toUpperCase();
      stamp(page, `Line ${String(i + 1).padStart(2, "0")}   Item ${value}   Quantity ${i + 3}   Checked / approved`,
        48, 680 - i * 20, 9.2, rgb(0.09, 0.09, 0.09), regular);
    }
    stamp(page, "End of sample A. The pale QR watermark intentionally crosses the text.", 42, 116, 9.2, ink.gray, regular);
  } else if (kind === "single-color") {
    // A small raster-free logo and colored headings stress color-aware masks.
    page.drawRectangle({ x: 466, y: 679, width: 65, height: 27, color: ink.blue });
    stamp(page, "TEST", 480, 687, 12, rgb(1, 1, 1), bold);
    stamp(page, "INSPECTION SUMMARY", 42, 699, 12, ink.blue, bold);
    stamp(page, "BLUE: approved     RED: needs attention     GREEN: cleared", 42, 678, 9, ink.maroon, regular);
    for (let i = 0; i < 20; i++) {
      const y = 648 - i * 24;
      const code = `ID-${String(i + 1).padStart(3, "0")}  ${(1193 * (i + 17)).toString(16).toUpperCase()}`;
      stamp(page, code, 46, y, 9.5, i % 3 === 0 ? ink.maroon : i % 3 === 1 ? ink.blue : ink.green, bold);
      stamp(page, `Verified item ${i + 1}; color and contrast test complete.`,
        205, y, 9.0, ink.gray, regular);
      page.drawLine({ start: { x: 44, y: y - 8 }, end: { x: 554, y: y - 8 },
        thickness: 0.35, color: rgb(0.77, 0.79, 0.83) });
    }
    stamp(page, "End of sample B. Keep the original page size when printing.", 42, 114, 9.2, ink.green, regular);
  } else {
    stamp(page, "High-entropy text / four balanced watermark fragments", 42, 709, 9.5, ink.navy, bold);
    // Deliberately incompressible text forces >1 QR's worth of signed bytes.
    // Keep it under the original page boundary and readable at 100% size.
    const rand = nextRand(0x0b1eaced);
    for (let i = 0; i < 54; i++) {
      const values = Array.from({ length: 9 }, () => rand().toString(16).padStart(8, "0")).join(" ");
      stamp(page, `R${String(i + 1).padStart(2, "0")} ${values}`, 43, 690 - i * 10.6, 7.45,
        rgb(0.10, 0.14, 0.19), mono);
    }
    stamp(page, "END QUADRANT CHALLENGE - scan all four parts from one photograph.", 43, 91, 8.4, ink.blue, regular);
  }
  return Buffer.from(await pdf.save());
}

async function makeInstructions() {
  const pdf = await PDFDocument.create();
  const page = pdf.addPage(pageSize);
  const bold = await pdf.embedFont(StandardFonts.HelveticaBold);
  const normal = await pdf.embedFont(StandardFonts.Helvetica);
  const lines = [
    ["QRED PRINT/CAMERA ACCEPTANCE PACK", 17, true],
    ["These pages are synthetic and signed with an openly published DEMO key.", 10, false],
    ["Never interpret these test seals as proof of an issuer's identity.", 10, false],
    ["", 8, false],
    ["PRINTING (US LETTER):", 12, true],
    ["1. Print the three *-SEALED.pdf files, not the *-SOURCE.pdf files.", 10, false],
    ["2. Set 100% / Actual size; do not fit, crop, or enlarge the page.", 10, false],
    ["3. Start with 300 DPI / Normal quality. Try 150 and 600 DPI afterward.", 10, false],
    ["4. Do not print from a screenshot or rasterized PDF preview.", 10, false],
    ["", 8, false],
    ["PHOTOGRAPHS:", 12, true],
    ["5. Place each page on a dark tabletop, then on a light tabletop.", 10, false],
    ["6. Include ALL FOUR paper corners in every unedited phone photograph.", 10, false],
    ["7. Take one overhead photo and one mildly angled photo of each sample.", 10, false],
    ["8. Turn off filters; keep the original JPG/HEIC, including EXIF if present.", 10, false],
    ["9. Use the QRed PR preview to verify each complete-page photograph.", 10, false],
    ["10. For sample C, require all 4 signed QR parts, not just one.", 10, false],
    ["", 8, false],
    ["REPORTING:", 12, true],
    ["Send the original photos, printer model, DPI/quality setting, phone model,", 10, false],
    ["which background was used, and any verification error or footer fallback.", 10, false],
    ["At 300 DPI, our acceptance target is 9 verified attempts out of 10.", 10, false],
    ["", 8, false],
    ["The public key is in demo-public-key.txt inside this pack.", 10, false],
    ["Print A -> B -> C and keep the sheets separate.", 10, false],
  ];
  let y = 744;
  for (const [line, size, strong] of lines) {
    if (line) stamp(page, line, 44, y, size, strong ? ink.navy : rgb(0, 0, 0), strong ? bold : normal);
    y -= line ? (size >= 16 ? 31 : size >= 12 ? 22 : 18) : 12;
  }
  return Buffer.from(await pdf.save());
}

const samples = [
  ["01-single-black", "single-black", 1],
  ["02-single-color-logo", "single-color", 1],
  ["03-quad-dense", "quad", 4],
];
const report = { generated: new Date().toISOString(), format: "US Letter 612 x 792 pt",
  key: signing.publicKey, samples: [] };
for (const [name, kind, expectedCount] of samples) {
  const originalBytes = await sampleDocument(kind);
  const file = new File([originalBytes], name + ".pdf", { type: "application/pdf" });
  console.log(`Generating ${name}, intended ${expectedCount} watermark part(s)...`);
  const result = await sealPdfInBrowser({
    file, ...signing, pageScalingStrategy: "watermark",
    encodingStrategy: kind === "quad" ? "plaintext" : "automatic",
  });
  const { blob, watermarkLayout, pageSealStrings, footerPages } = result;
  const parts = pageSealStrings[0];
  assert.equal(parts.length, expectedCount,
    `${name} produced ${parts.length} part(s), expected ${expectedCount}`);
  assert.deepEqual(footerPages, [], `${name} fell back to a footer`);
  assert.equal(watermarkLayout[0]?.pageAligned, true,
    `${name} did not get a page-filling rectangular watermark`);
  const sealedBytes = Buffer.from(await blob.arrayBuffer());
  const loaded = await PDFDocument.load(sealedBytes);
  assert.equal(loaded.getPageCount(), 1);
  assert.deepEqual(loaded.getPage(0).getSize(), { width: 612, height: 792 });
  const results = await withPdfDocument(blob, async pdf =>
    scanPdfPage(await renderPdfPage(pdf, 1, 2)));
  assert.deepEqual(new Set(results.seals), new Set(parts),
    `${name} full-page digital scan does not recover every exact signed part`);
  const verified = await verifyQRedSeals(results.seals.toReversed(), signing.publicKey);
  assert.equal(verified.status, "VALID", `${name} digital signature check: ${verified.status}`);
  const sourcePath = join(out, name + "-SOURCE.pdf");
  const printPath = join(out, name + "-SEALED.pdf");
  writeFileSync(sourcePath, originalBytes);
  writeFileSync(printPath, sealedBytes);
  const details = { name, source: name + "-SOURCE.pdf", print: name + "-SEALED.pdf",
    format: "watermark-1-or-4", pageAligned: true, signedParts: parts.length,
    qrVersions: parts.map(seal => createQRedQrSymbol(seal).version),
    pageSize: loaded.getPage(0).getSize(), fullPageDigitalScan: "VALID",
    footerPages: [], originalBytes: originalBytes.length, sealedBytes: sealedBytes.length };
  report.samples.push(details);
  console.log(JSON.stringify(details));
}
writeFileSync(join(out, "demo-public-key.txt"), signing.publicKey + "\n");
writeFileSync(join(out, "PRINT-AND-PHOTO-INSTRUCTIONS.pdf"), await makeInstructions());
writeFileSync(join(out, "DIGITAL-TEST-RESULTS.json"), JSON.stringify(report, null, 2) + "\n");
writeFileSync(join(out, "START-HERE.txt"), [
  "QRed experimental page-filling watermarks: physical print/camera handoff",
  "",
  "Print only the *-SEALED.pdf documents at 100% actual size on US Letter paper.",
  "Test A is a single watermark beneath black text.",
  "Test B is a single watermark beneath colored text and a small logo.",
  "Test C is four adjacent watermark fragments: all 4 are required to verify.",
  "",
  "Start at 300 DPI (normal quality), then also try 150/600 DPI if supported.",
  "Photograph each printed sheet against both dark and pale surfaces.",
  "Include all four corners; take overhead and off-axis photos; do not edit.",
  "Use the QRed PR preview to verify the photos: ",
  "https://feature-module-aware-color-and-quad-watermarks-qred.greyphilosophy.workers.dev",
  "For local v3 test seals, use demo-public-key.txt (this key is NOT an identity).",
  "Share the original photos, printer make/model/DPI, phone model and results.",
  "",
  "These are generated synthetic samples, not personal or official documents.",
  "DIGITAL-TEST-RESULTS.json records the exact observed digital signed scans.",
].join("\n") + "\n");
console.log("READY FOR PHYSICAL PRINT/CAMERA TEST", JSON.stringify({ directory: out, examples: report.samples.length }));
